167	static int pan_send_setup_req(void)
168	{
169	  uint8_t frame[16];
170	  int32_t n = pw_bnep_build_setup_req(frame, sizeof(frame), PW_BNEP_UUID_PANU,
171	                                      PW_BNEP_UUID_NAP);
172	  if (n < 0)
173	    {
174	      return (int)n;
175	    }
176	
177	  printf("[pan] send SETUP_CONNECTION_REQ (pANU->NAP)\n");
178	  return pan_send_raw(frame, (uint32_t)n);
179	}
