181	static int pan_send_filter(void)
182	{
183	  static const struct pw_bnep_ftype ranges[] =
184	  {
185	    { PW_BNEP_ETH_IPV4, PW_BNEP_ETH_IPV4 },
186	    { PW_BNEP_ETH_ARP,  PW_BNEP_ETH_ARP  },
187	  };
188	
189	  uint8_t frame[16];
190	  int32_t n = pw_bnep_build_filter_set(frame, sizeof(frame), ranges,
191	                                       (uint8_t)(sizeof(ranges) / sizeof(ranges[0])));
192	  if (n < 0)
193	    {
194	      return (int)n;
195	    }
196	
197	  printf("[pan] send FILTER_NET_TYPE_SET (ipv4+arp)\n");
198	  return pan_send_raw(frame, (uint32_t)n);
199	}
