205	static int pan_tun_open(void)
206	{
207	  struct ifreq ifr;
208	  int          fd;
209	
210	  fd = open("/dev/tun", O_RDWR | O_NONBLOCK);
211	  if (fd < 0)
212	    {
213	      printf("[pan] open /dev/tun err=%d\n", errno);
214	      return -errno;
215	    }
216	
217	  memset(&ifr, 0, sizeof(ifr));
218	  strncpy(ifr.ifr_name, PW_PAN_TUN_NAME, sizeof(ifr.ifr_name) - 1);
219	  ifr.ifr_flags = IFF_TAP | IFF_NO_PI;          /* [已核实] net/if.h: #define ifr_flags ifr_ifru.ifru_flags (uint32_t) */
220	
221	  if (ioctl(fd, TUNSETIFF, (unsigned long)&ifr) < 0)
222	    {
223	      printf("[pan] TUNSETIFF err=%d\n", errno);
224	      close(fd);
225	      return -errno;
226	    }
227	
228	  g_pan.tunfd = fd;
229	  printf("[pan] tun ready: %s (tap)\n", ifr.ifr_name);
230	
231	  /* 注意：接口地址由 `dhcpc -i tun0` 或手动 ifconfig 决定，本模块不配 IP。
232	   * 建议在 `phywear pan on` 成功后由 NSH 侧跑一次 dhcpc（见 BOARD §12 验收）。
233	   */
234	
235	  return 0;
236	}
