409	static uint8_t pan_sdp_done(struct bt_conn *conn, struct bt_sdp_client_result *result,
410	                            const struct bt_sdp_discover_params *params)
411	{
412	  uint16_t psm = PW_PAN_PSM_UNKNOWN;
413	  int      err;
414	
415	  (void)params;
416	
417	  if (result == NULL || result->resp_buf == NULL)
418	    {
419	      pan_fail("sdp: no NAP record (phone hotspot off?)");
