522	/* ---------------------------------------------------------------------------
523	 * 对外 API
524	 * ------------------------------------------------------------------------- */
525	
526	static int pan_thread_start(void)
527	{
528	  pthread_attr_t attr;
529	  int            err;
530	
531	  if (g_pan.thread_started)
532	    {
533	      return 0;
534	    }
535	
536	  g_pan.thread_run = true;
537	  pthread_attr_init(&attr);
538	  pthread_attr_setstacksize(&attr, 6144);
539	  pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
540	
541	  err = pthread_create(&g_pan.thread, &attr, pan_tun_thread, NULL);
542	  pthread_attr_destroy(&attr);
543	  if (err != 0)
544	    {
545	      printf("[pan] pthread_create err=%d\n", err);
546	      g_pan.thread_run = false;
547	      return -err;
548	    }
549	
550	  g_pan.thread_started = true;
551	  return 0;
552	}
