554	static void pan_reset(void)
555	{
556	  if (g_pan.conn != NULL)
557	    {
558	      bt_conn_unref(g_pan.conn);
559	      g_pan.conn = NULL;
560	    }
561	
562	  g_pan.state = PW_PAN_IDLE;
563	  g_pan.psm   = PW_PAN_PSM_UNKNOWN;
564	}
