653	                  pan_state_name(g_pan.state), g_pan.psm,
654	                  g_pan.tunfd >= 0 ? PW_PAN_TUN_NAME : "-",
655	                  (unsigned long)g_pan.rx_frames, (unsigned long)g_pan.tx_frames,
656	                  (unsigned long)g_pan.rx_drop, (unsigned long)g_pan.tx_err,
657	                  g_pan.last_err[0] ? " err=" : "",
658	                  g_pan.last_err[0] ? g_pan.last_err : "");
659	}
